/// <summary>
/// Generates pipe-delimited condition string from packed query
/// </summary>
public Notes getConditions(METFulfilmentProfileId _profileId)
{
    Notes queryString;
    container packedQuery = METFulfilmentProfile::find(_profileId).ConditionQueryPacked;

    Query condition;
    int dsN;
    int dsI;

    void addFilter(Query _query)
    {
        int nFilter = _query.queryFilterCount();
        int iFilter;

        for (iFilter = 1; iFilter <= nFilter; iFilter++)
        {
            QueryFilter qf = _query.queryFilter(iFilter);

            if (qf.value() && qf.status() != RangeStatus::Hidden)
            {
                QueryBuildDataSource qbds = qf.dataSource();
                TableId tableId = qbds.table();
                FieldId fieldId = fieldName2Id(tableId, qf.field());

                queryString += strFmt("%1; %2; %3|", tableId, fieldId, qf.value());
            }
        }
    }

    void addRange(QueryBuildRange _range)
    {
        if (_range.value() && _range.status() != RangeStatus::Hidden)
        {
            queryString += strFmt("%1; %2; %3|", _range.table(), _range.field(), _range.value());
        }
    }

    void addDatasource(QueryBuildDataSource _ds)
    {
        int nRange = _ds.rangeCount();
        int iRange;
        for (iRange = 1; iRange <= nRange; iRange++)
        {
            addRange(_ds.range(iRange));
        }
    }

    if (conLen(packedQuery) > 0)
    {
        condition = new Query(packedQuery);
        dsN = condition.dataSourceCount();
        for (dsI = 1; dsI <= dsN; dsI++)
        {
            addDatasource(condition.dataSourceNo(dsI));
        }

        addFilter(condition);
    }

    return queryString;
}

/// <summary>
/// Post load method to convert query conditions to string on export
/// </summary>
public void postLoad()
{
    super();

    if (this.ProfileId)
    {
        this.Conditions = this.getConditions(this.ProfileId);
    }
}

/// <summary>
/// Builds the fulfilment condition query from a serialised condition string.
/// </summary>
/// <param name = "_conditions">Pipe delimited conditions, each line tableId; fieldId; value.</param>
/// <param name = "_profileId">Profile id, used for logging only.</param>
/// <returns>The condition query, based on METFulfilmentProfile::defaultQuery.</returns>
public static Query buildConditionQuery(str _conditions, METFulfilmentProfileId _profileId)
{
    Query                   query;
    List                    conditionsList;
    ListEnumerator          conditionsEnum;
    List                    conditionParts;
    ListEnumerator          conditionPartsEnum;
    QueryBuildDataSource    qbds;
    QueryBuildRange         qbr;
    QueryFilter             queryFilter;
    FieldName               conditionFieldName;
    str                     condition;
    str                     partVal;
    str                     value;
    TableId                 tableId;
    FieldId                 fieldId;
    Counter                 partCounter;

    // Always start from defaultQuery so the AOT structure of METFulfilmentConditionQuery is preserved.
    query = METFulfilmentProfile::defaultQuery();

    if (!_conditions)
    {
        return query;
    }

    conditionsList = strSplit(_conditions, '|');
    conditionsEnum = conditionsList.getEnumerator();

    while (conditionsEnum.moveNext())
    {
        condition = strLTrim(strRTrim(conditionsEnum.current()));

        if (!condition)
        {
            continue;
        }

        conditionParts     = strSplit(condition, ';');
        conditionPartsEnum = conditionParts.getEnumerator();
        tableId     = 0;
        fieldId     = 0;
        value       = '';
        partCounter = 1;

        while (conditionPartsEnum.moveNext())
        {
            partVal = strLTrim(strRTrim(conditionPartsEnum.current()));

            if (partCounter == 1)
            {
                tableId = str2Int(partVal);
            }
            else if (partCounter == 2)
            {
                fieldId = str2Int(partVal);
            }
            else if (partCounter == 3)
            {
                value = partVal;
            }

            partCounter++;
        }

        if (!tableId || !fieldId)
        {
            warning(strFmt('@MET:TableConditionQuery',
                _profileId, condition));
            continue;
        }

        qbds = query.dataSourceTable(tableId);

        if (!qbds)
        {
            warning(strFmt('@MET:FieldconditionQuery',
                _profileId, tableId));
            continue;
        }

        conditionFieldName = fieldId2Name(tableId, fieldId);

        if (!conditionFieldName)
        {
            warning(strFmt('@MET:FieldconditionQuery',
                _profileId, fieldId, tableId));
            continue;
        }

        if (qbds.joinMode() == JoinMode::OuterJoin)
        {
            queryFilter = SysQuery::findOrCreateQueryFilter(query, qbds, conditionFieldName);

            if (queryFilter)
            {
                queryFilter.value(value);
            }
        }
        else
        {
            qbr = qbds.findRange(fieldId);

            if (!qbr)
            {
                qbr = qbds.addRange(fieldId);
            }

            qbr.value(value);
        }
    }

    return query;
}

/// <summary>
/// Maps the unmapped Conditions string back to the packed query on import.
/// </summary>
/// <param name = "_entityCtx">Entity runtime context.</param>
/// <param name = "_dataSourceCtx">Data source runtime context.</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    METFulfilmentProfile fulfilmentProfile;

    super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() != dataEntityDataSourceStr(METFulfilmentProfileEntity, METFulfilmentProfile)
        || !this.Conditions)
    {
        return;
    }

    fulfilmentProfile = _dataSourceCtx.getBuffer() as METFulfilmentProfile;

    if (fulfilmentProfile)
    {
        fulfilmentProfile.ConditionQueryPacked =
            METFulfilmentProfileEntity::buildConditionQuery(this.Conditions, this.ProfileId).pack();
    }
}

/// <summary>
/// This runs even when the framework processes the entity set based and skips mapEntityToDataSource.
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">Definition group execution.</param>
public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    METFulfilmentProfileStaging staging;
    METFulfilmentProfile        fulfilmentProfile;

    while select staging
        where staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
           && staging.ExecutionId     == _dmfDefinitionGroupExecution.ExecutionId
    {
        if (!staging.ProfileId || !staging.Conditions)
        {
            continue;
        }

        ttsbegin;

        select firstonly forupdate fulfilmentProfile
            where fulfilmentProfile.ProfileId == staging.ProfileId;

        if (fulfilmentProfile.RecId)
        {
            fulfilmentProfile.ConditionQueryPacked =
                METFulfilmentProfileEntity::buildConditionQuery(staging.Conditions, staging.ProfileId).pack();
            fulfilmentProfile.update();
        }

        ttscommit;
    }
}
